let chatId = '';
let rawText = '';
let location = '';

try {
  const payload = $('Execute Workflow Trigger').item.json;
  const msg = payload.message || payload.body?.message || payload;
  chatId = msg?.chat?.id || payload.chatId || '';
  rawText = String(msg?.text || payload.text || payload.query || '').trim();
} catch (error) {}

location = rawText
  .replace(/^(thoi tiet|thời tiết|weather|nhiet do|nhiệt độ|troi|trời|du bao thoi tiet|dự báo thời tiết)\s*/i, '')
  .replace(/^(tai|tại|o|ở|cho|cho toi|cho tôi|hom nay|hôm nay)\s*/i, '')
  .trim();

if (!location) location = 'Ho Chi Minh City';

return [{
  json: {
    chatId,
    rawText,
    location
  }
}];

const source = $('Chuẩn Bị Địa Điểm').item.json;
const raw = $json?.data ?? $json;
const data = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
const chatId = source.chatId;
const fallbackLocation = source.location;

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const current = Array.isArray(data.current_condition) ? data.current_condition[0] || {} : {};
const today = Array.isArray(data.weather) ? data.weather[0] || {} : {};
const nearest = Array.isArray(data.nearest_area) ? data.nearest_area[0] || {} : {};
const request = Array.isArray(data.request) ? data.request[0] || {} : {};
const requestQuery = request.query || '';
const areaName = nearest.areaName?.[0]?.value || fallbackLocation;
const country = nearest.country?.[0]?.value || '';
const region = nearest.region?.[0]?.value || '';
const desc = current.weatherDesc?.[0]?.value || '';
const feelsLike = current.FeelsLikeC || '';
const tempC = current.temp_C || '';
const humidity = current.humidity || '';
const windKmph = current.windspeedKmph || '';
const rainMm = current.precipMM || '0';
const maxTemp = today.maxtempC || '';
const minTemp = today.mintempC || '';
const sunrise = today.astronomy?.[0]?.sunrise || '';
const sunset = today.astronomy?.[0]?.sunset || '';

let locationLine = requestQuery || areaName || fallbackLocation;
if (region && !locationLine.includes(region)) locationLine += `, ${region}`;
if (country && !locationLine.includes(country)) locationLine += `, ${country}`;

let message = '🌦 <b>Thời tiết hiện tại</b>\n';
message += `<i>${escapeHtml(locationLine)}</i>\n\n`;

if (tempC !== '') {
  message += `🌡 <b>Nhiệt độ:</b> ${escapeHtml(tempC)}°C`;
  if (feelsLike !== '') message += ` • Cảm giác như ${escapeHtml(feelsLike)}°C`;
  message += '\n';
}

if (desc) message += `☁️ <b>Tình trạng:</b> ${escapeHtml(desc)}\n`;
if (humidity !== '') message += `💧 <b>Độ ẩm:</b> ${escapeHtml(humidity)}%\n`;
if (windKmph !== '') message += `💨 <b>Gió:</b> ${escapeHtml(windKmph)} km/h\n`;
if (rainMm !== '') message += `🌧 <b>Lượng mưa:</b> ${escapeHtml(rainMm)} mm\n`;
if (maxTemp !== '' || minTemp !== '') message += `📈 <b>Hôm nay:</b> ${escapeHtml(minTemp)}°C - ${escapeHtml(maxTemp)}°C\n`;
if (sunrise || sunset) message += `🌅 <b>Mặt trời:</b> ${escapeHtml(sunrise)} / ${escapeHtml(sunset)}\n`;

if (tempC === '' && !desc) {
  message = `⚠️ Không lấy được dữ liệu thời tiết cho <b>${escapeHtml(fallbackLocation)}</b>. Bạn thử ghi rõ địa điểm hơn nhé.`;
}

message = message.trim();
return [{ json: { chatId, text: message } }];
